document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".hb-toc ul ul");e.forEach(e=>{e.classList.add("hidden");const t=e.previousElementSibling;t&&t.tagName==="LI"&&t.classList.remove("open")});const t=document.querySelectorAll("[data-hb-toc-toggle]");t.forEach(e=>{e.addEventListener("click",function(){const e=this.closest("li"),t=e.nextElementSibling;e&&t&&t.tagName==="UL"&&(e.classList.toggle("open"),t.classList.toggle("hidden"))})})})